window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Tryb przypuszczający (Konjunktiv II) i zdania z wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Na twoim miejscu …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"Rzeczywistość Evy – życzenia Evy. Uzupełnij: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Ale chciałaby być wyższa.","why":"*grösser sein*: forma życzenia od *sein* to **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Ale chciałaby dobrze mówić po hiszpańsku.","why":"Na końcu stoi bezokolicznik (*sprechen*), więc życzenie to **würde** + bezokolicznik.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Ale wolałaby pracować jako przewodniczka wycieczek.","why":"Bezokolicznik na końcu (*arbeiten*) → **würde** + bezokolicznik. *lieber* = raczej, chętniej.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Ale chciałaby mieć duże mieszkanie.","why":"*eine Wohnung haben*: forma życzenia od *haben* to **hätte**. Bezokolicznik nie jest potrzebny.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Co myślą ci ludzie?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Dopasuj każdy obrazek do wyrażenia z ramki.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Gdybym nie musiał pracować, siedziałbym teraz w ogrodzie.","why":"Obrazek 1 pokazuje go przy pracy, a potem jak marzy na leżaku. Po zdaniu z *wenn* zdanie główne zaczyna się od czasownika (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Gdybym miał samochód, nie musiałbym jeździć na rowerze w deszczu.","why":"Jedzie na rowerze w deszczu; samochód by mu tego oszczędził. *müsste* to Konjunktiv II od *müssen*. *Velo* to szwajcarskie słowo na *Fahrrad* (rower).","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Gdyby autobus nie miał opóźnienia, byłabym punktualnie w biurze.","why":"Przez spóźniony autobus ona spóźnia się do pracy. *wäre* to Konjunktiv II od *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Przepisz zdania z a: zacznij od zdania głównego, potem zdanie z wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Nie musiałbym jeździć na rowerze w deszczu, gdybym miał samochód.","why":"Najpierw zdanie główne, potem zdanie z *wenn*. W zdaniu z *wenn* czasownik (*hätte*) idzie na koniec.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Byłabym punktualnie w biurze, gdyby autobus nie miał opóźnienia.","why":"Ten sam wzór: zdanie główne, przecinek, *wenn* … czasownik na końcu (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij słowami z ramki. Każde słowo jest użyte raz; przekreślone są użyte w przykładzie.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Zrobiłabym niektóre rzeczy inaczej, gdybym była szefową w naszej firmie.","why":"*machen* na końcu → **würde** + bezokolicznik. *Chefin sein* → **wäre**, na końcu zdania z *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Gdybym był Markiem, koniecznie zacząłbym naukę zawodu.","why":"*Marco sein* → **wäre** (jak w *Wenn ich du wäre …*). Zdanie główne ma bezokolicznik *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Gdybym mogła swobodnie decydować, pracowałabym w małej firmie.","why":"*frei entscheiden können* → **könnte** na końcu zdania z *wenn*. Zdanie główne z *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Gdybyśmy mieli dzieci, musiałabym pracować tylko na pół etatu.","why":"*Kinder haben* z *wir* → **hätten**. Ramka zostawia **müsste** na ostatnią lukę.","source":"k2","check":"W b, c i e zarówno *müsste*, jak i *würde* są poprawne po niemiecku (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* jest równie dobre). Ramka mówi tylko, które trzy luki dostają *würde*, a która *müsste*; ten klucz to najbardziej prawdopodobny podział. Zapytaj nauczyciela, którą wersję chce książka."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Muszę się spieszyć z powodu pracy.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Przepisz odpowiedzi, używając spójnika weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Bo moja dziewczyna jest niepunktualna.","why":"*wegen* + rzeczownik zamienia się w *weil* + zdanie z czasownikiem; czasownik (*ist*) idzie na koniec.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Bo pogoda jest zła.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; po *weil* czasownik idzie na koniec.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Bo mam ważne spotkanie.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (biernik po *haben*); czasownik na końcu.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Uzupełnij: wegen – weshalb – weil – deswegen – denn. Jednego słowa można użyć więcej niż raz.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Słabo go rozumiem z powodu jego wymowy.","why":"Dalej stoi rzeczownik (*seiner Aussprache*, dopełniacz), a nie zdanie → przyimek **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Kiedyś chciałbym pojechać do Włoch, bo chciałbym zobaczyć morze.","why":"Po luce czasownik zostaje na drugim miejscu (*ich möchte*) → **denn**. Z *weil* poszedłby na koniec.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Muszę poprawić rozumienie ze słuchu, dlatego oglądam dużo filmów.","why":"Druga część to skutek, a czasownik stoi zaraz po luce (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Moje dzieci szybko nauczyły się niemieckiego, bo w przedszkolu zawsze są razem ze szwajcarskimi dziećmi.","why":"Czasownik jest na końcu (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Dlaczego zapisujesz słowa na karteczkach?","why":"Potrzebny jest zaimek pytający: **Weshalb** znaczy *warum* (dlaczego)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Moja siostra mówi już prawie płynnie po niemiecku, dlatego może mi pomagać w nauce niemieckiego.","why":"Skutek, a czasownik stoi zaraz po luce (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Na kursie językowym. Uzupełnij: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Nie mogłem zrobić ostatniego ćwiczenia, bo go nie zrozumiałem.","why":"Czasownik jest na końcu (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"W rejestracji nikogo nie było. Dlatego wróciłem do domu.","why":"Nowe zdanie, które podaje skutek, z czasownikiem zaraz po luce (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Ze względu na dobre oceny nie musiałem pisać testu na początku kursu.","why":"Dalej stoi grupa rzeczownikowa (*meiner guten Noten*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Jest dodatkowy kurs językowy, bo zapisało się bardzo wielu uczestników.","why":"Czasownik jest na końcu (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Wczoraj niestety nie mogłem przyjść na kurs z powodu bólu zębów.","why":"Dalej stoi grupa rzeczownikowa (*meiner Zahnschmerzen*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Kto znajdzie najlepsze wymówki? Wybierz jedną sytuację i napisz. Przykładowe odpowiedzi to tylko jedna z możliwości.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Niestety nie mogłem posprzątać kuchni, bo nagle bardzo rozbolały mnie plecy. Musiałem się położyć. Dlatego obejrzałem film.","why":"Używa *weil* (czasownik na końcu: *hatte*) i *Deswegen* (czasownik zaraz po nim: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Z powodu grypy nie poszedłem na egzamin końcowy. Miałem wysoką gorączkę, dlatego zostałem w łóżku.","why":"Używa *wegen* + dopełniacz (*einer Grippe*) i *deswegen* + czasownik (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Bardzo mi przykro! Niestety się spóźniłem, bo na autostradzie był wypadek. Przez korek straciłem dwie godziny.","why":"*denn* zostawia czasownik na drugim miejscu (*war*). *wegen des Staus*: dopełniacz od *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (zdania warunkowe, także nierzeczywiste z Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"słownik spójników grammis: wenn (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"słownik spójników grammis: weil (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (przyczynowy, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen z dopełniaczem)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Dorastanie z kilkoma językami · czytanie, wpis na forum, krzyżówka, ulubione słowa","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Dwa lub trzy języki w jednej rodzinie – żaden problem?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Kto co mówi? Przeczytaj trzy teksty i przy każdym zdaniu napisz imię osoby, która je mówi.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"„Dzieci chcą mówić tym samym językiem co ich przyjaciele.” – Janusz","why":"Janusz (tekst B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"„Przecież to dobrze, kiedy ktoś bardzo dobrze mówi w kilku językach.” – Yara","why":"Yara (tekst C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"„Moje dzieci przeskakują między dwoma językami.” – Amira","why":"Amira (tekst A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Tylko ona mówi o swoich własnych dzieciach."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Co jest prawdą? Przeczytaj teksty jeszcze raz. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Dzieci Amiry mówią lepiej po arabsku niż po niemiecku. → prawda","why":"Rodzina zawsze mówi w domu po arabsku: *Darum können das die Kinder viel besser.* (Ich niemiecki to tutaj szwajcarski niemiecki.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"W rodzinie Amiry mówi się tylko po niemiecku. → fałsz","why":"Odwrotnie: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz uczył się niemieckiego przez sześć lat. → fałsz","why":"Miał sześć lat, kiedy rodzina się przeprowadziła (*als ich sechs Jahre alt war*), a po roku mówił płynnie standardowym niemieckim (Hochdeutsch)."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz i jego siostra nie chcieli mówić z rodzicami po polsku. → prawda","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara mówi płynnie w trzech językach. → prawda","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* Niemiecki to jej czwarty język i jeszcze nie mówi nim dobrze."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara wkrótce zacznie też uczyć się niemieckiego. → fałsz","why":"Nie zaczyna wkrótce (*bald*): uczy się niemieckiego już od dwóch lat (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Napisz wpis na forum. Po debacie telewizyjnej o dorastaniu z kilkoma językami znajdujesz na forum internetowym programu taką opinię:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Zrób notatki do czterech pytań. Wystarczą krótkie notatki, bez pełnych zdań. Przykładowe notatki to jedna z możliwości.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Tak: syn mojej sąsiadki – włoski z mamą, szwajcarski niemiecki w szkole","why":"Tylko notatki: imię lub osoba i jakie języki gdzie."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"nauka dwóch języków bez kursu, kontakt z rodziną za granicą, korzyści w pracy","why":"Zbierz dwie lub trzy zalety; będą ci potrzebne do *Ich finde es sehr gut, dass …* w b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mieszanie języków, jeden język jest słabszy, dużo pracy dla rodziców","why":"To trafi do *Es könnte schwierig sein, dass …* i *Auf der anderen Seite …* w b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"nie – dzieci dobrze uczą się dwóch języków, jeśli rodzice dużo z nimi rozmawiają","why":"Zdecyduj, czy tak, czy nie, i podaj jeden powód – z tego powstanie *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Teraz napisz swoją opinię na ten temat (około 80 słów). Wykorzystaj swoje notatki z punktu a i kilka podanych zwrotów.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Nie zgadzam się z Sandrą, bo wiele dzieci uczy się dwóch języków bez problemów. Syn mojej sąsiadki dorasta z włoskim i niemieckim. Z mamą mówi po włosku, a w szkole szwajcarskim niemieckim. Uważam, że to bardzo dobrze, że tak wcześnie uczy się dwóch języków. Trudne mogłoby być to, że czasem miesza języki. Z drugiej strony u małych dzieci to normalne. Najważniejsze ze wszystkiego jest to, żeby rodzice dużo rozmawiali z dzieckiem. Dlatego każde z rodziców powinno mówić swoim własnym językiem.","why":"Około 85 słów, z sześcioma zwrotami. *denn* zostawia czasownik na drugim miejscu (*lernen*); po *Deswegen* czasownik stoi zaraz potem (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Rozwiąż krzyżówkę. Każde zdanie podaje pierwszą literę brakującego słowa. Siatki tu nie ma: wpisz całe słowo. W siatce w książce Ä zajmuje jedną kratkę.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Naszą ojczyzną jest Hiszpania. Pochodzimy z Hiszpanii.","why":"*aus einem Land stammen* = pochodzić z jakiegoś kraju (jak *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda i Mike nie widzą się przez sześć miesięcy. To długa rozłąka.","why":"*die Trennung* = rozłąka, rozstanie, rzeczownik od *sich trennen*. *eine lange* → rzeczownik rodzaju żeńskiego."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"Niemiecki i arabski nie mają tego samego pisma.","why":"*die Schrift* = pismo, czyli litery, którymi zapisuje się język. Arabski używa innego alfabetu."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter mieszka teraz w Ameryce. Odkąd tam mieszka, bardzo się zmienił.","why":"*sich verändern* = zmieniać się (o człowieku). Perfekt: *hat sich verändert*. Ä zajmuje jedną kratkę."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Ona pisze książki. Z zawodu jest autorką.","why":"*Sie* → forma żeńska z *-in*: *der Autor → die Autorin*. Po *sein … von Beruf* nie ma rodzajnika."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Dzieci nie odrabiają zadań domowych. Dlatego rodzice na nie krzyczą.","why":"*mit jemandem schimpfen* = besztać kogoś, krzyczeć na kogoś. Podmiot w liczbie mnogiej *die Eltern* → *schimpfen*. Po *Deshalb* czasownik stoi zaraz potem."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Pracuje dopiero od kilku miesięcy. Ma jeszcze niewielkie doświadczenie w zawodzie.","why":"*die Erfahrung* = doświadczenie. *wenig Erfahrung haben* = mieć niewielkie doświadczenie."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Teraz mamy chaos. Wszystko jest pomieszane.","why":"*durcheinander sein* = być w nieładzie, pomieszanym. Pisane łącznie."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Dla Ye-Jon głoski P i F brzmią tak samo. Nie potrafi ich rozróżnić.","why":"*unterscheiden* = rozróżniać. Z *kann* bezokolicznik idzie na koniec. *tönen* to szwajcarskie słowo na *klingen* (brzmieć)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Na wakacje jadę do Grecji, ale niestety w ogóle nie mówię po grecku.","why":"*Griechisch* = język grecki, wielką literą. *kein Griechisch können* = w ogóle nie mówić po grecku."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"On je tylko warzywa i ryż. Je wyłącznie warzywa i ryż.","why":"*ausschliesslich* = wyłącznie, nic poza tym. Pisownia szwajcarska z *ss*; w Niemczech pisze się to z ostrym s (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Hasło (zaznaczony rząd w siatce): język ojczysty","why":"Każde słowo daje jedną literę zaznaczonego rzędu: stam**M**en, trenn**U**ng, schrif**T**, (T w siatce), veränd**E**rt, auto**R**in, (S w siatce), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Moje najpiękniejsze niemieckie słowo","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Dopasuj każde zdjęcie do słowa z ramki. Kolorowe kropki w książce podają rodzajnik: niebieska = der, zielona = das, czerwona = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (deser: krem z karmelem)","why":"Szwajcarska nazwa crème caramel. *Chöpfli* to w szwajcarskim niemieckim „główka” (*Kopf*). Zielona kropka → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – spadająca gwiazda","why":"*der Stern* = gwiazda; *die Sternschnuppe* = spadająca gwiazda. Czerwona kropka → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – motyl","why":"Szwajcarskie słowo na *der Schmetterling* (motyl); Duden oznacza je *schweizerisch, sonst landschaftlich*. Niebieska kropka → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Dlaczego ktoś może uważać właśnie te słowa za najpiękniejsze? Co o tym myślisz? Zrób notatki, potem o nich porozmawiajcie. Przykładowe notatki to jedna z możliwości.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"takie kolorowe i lekkie, przypomina lato, zabawne: to zwierzę wcale nie jest ptakiem","why":"Pomyśl, co to słowo każe ci zobaczyć lub poczuć i jak brzmi."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"słodkie, przypomina dzieciństwo, brzmi zabawnie i typowo szwajcarsko","why":"*tönen* to szwajcarskie słowo na *klingen* (brzmieć)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantyczne, można sobie czegoś życzyć, brzmi miękko","why":"Wystarczą krótkie notatki: przymiotniki i powód."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Moje ulubione słowo","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Które niemieckie słowo i które słowo w twoim języku ojczystym lubisz? Dlaczego? Napisz krótki tekst, korzystając ze zwrotów. Przykładowa odpowiedź to jedna z możliwości.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Moje ulubione niemieckie słowo to „gemütlich” (przytulny, swojski). Kiedy słyszę to słowo, myślę o zimowym wieczorze z herbatą, świecami i przyjaciółmi. Dlatego wydaje mi się takie ładne. Brzmi miękko i ciepło. W moim języku ojczystym, angielskim, nie ma słowa o dokładnie takim znaczeniu. Po angielsku podoba mi się słowo „sunshine”. Dla mnie to radosne słowo, bo brzmi jasno i przyjaźnie.","why":"*Wenn …, dann* + czasownik zaraz potem (*denke ich*); *Deshalb* + czasownik zaraz potem (*finde ich*). Wstaw własny język ojczysty i własne słowa.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Przedstaw swój tekst na zajęciach. Możliwy początek pokazuje przykład.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Chciałbym wam dziś przedstawić moje ulubione słowo. To słowo „gemütlich”. …","why":"Zacznij od podania słowa, potem przeczytaj swój tekst z a. *euch* do kolegów z grupy, *Ihnen*, jeśli mówisz oficjalnie."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"słownik spójników grammis: wenn (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Grzeczne dopytywanie, nauka języków, szukanie pracy · test z lekcji 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (oficjalny klucz odpowiedzi, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (zdania warunkowe, także nierzeczywiste z Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"słownik spójników grammis: weil (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (przyczynowy, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"słownik spójników grammis: deshalb (skutek; synonimy daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"słownik spójników grammis: d(a)rum (skutek)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen z dopełniaczem)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Przepraszam, czy mógłby Pan to powtórzyć?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij każde pytanie lub zdanie początkiem z ramki. Każdy początek jest użyty raz; przekreślony jest użyty w przykładzie.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Co znaczy wyrażenie „es eilig haben”?","why":"*Was bedeutet …?* pyta o znaczenie słowa lub wyrażenia. (*es eilig haben* = spieszyć się.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Czy mógłby Pan mówić trochę wolniej?","why":"*Könnten Sie …* (Konjunktiv II) sprawia, że prośba jest grzeczna; bezokolicznik *sprechen* idzie na koniec.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Przepraszam, nie zrozumiałem tego słowa.","why":"Perfekt: *habe … verstanden*; *das Wort* stoi na początku dla podkreślenia, więc czasownik *habe* stoi zaraz po nim.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Słucham? Czy mógłby Pan to powtórzyć?","why":"Grzeczna prośba z *Könnten Sie …*; *wiederholen* (powtórzyć) idzie na koniec.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Czy wie Pani, czy są tu też kursy integracyjne?","why":"*ob* wprowadza zależne pytanie typu tak/nie, więc czasownik *gibt* idzie na koniec.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Przepraszam, czy dobrze to zrozumiałem?","why":"Pytanie typu tak/nie w czasie Perfekt: *habe* na początku, *verstanden* na końcu.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Czy mogłaby mi Pani powiedzieć, gdzie jest stołówka?","why":"Pytanie zależne z *wo*: czasownik *ist* idzie na koniec. *die Mensa* = stołówka uczelniana.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij dialogi. Wydrukowane pierwsze litery (i kilka liter w środku słów) są podane; wpisz całe brakujące słowa.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Słucham? Nie zrozumiałam ostatniego słowa.","why":"Perfekt: *habe* na drugim miejscu po *Das letzte Wort*, *verstanden* na końcu.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Przepraszam, tu jest tak głośno. Czy mogłaby Pani powtórzyć godzinę spotkania?","why":"Grzeczna prośba: *Könnten Sie* … bezokolicznik *wiederholen* na końcu. *der Termin* to tutaj godzina spotkania.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Czy mogę Pana o coś zapytać? – Tak, oczywiście. – Czy wie Pan, czy w pociągu do Genewy o 14.33 jest też bistro albo wagon restauracyjny?","why":"*Darf ich Sie etwas fragen?* grzecznie otwiera rozmowę; *ob* zaczyna zależne pytanie typu tak/nie, więc *gibt* idzie na koniec.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Ułóż słowa z sylab w ramce i uzupełnij zdania. Przekreślone sylaby (Men, sa) są użyte w przykładzie.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"Mój samochód znowu się zepsuł. Czy mógłbyś mi jeszcze raz dać numer telefonu do twojego dobrego mechanika? Tym razem chcę go od razu zapisać w notesie z adresami, żeby znowu go nie zgubić.","why":"Me-cha-ni-ker (osoba, która naprawia samochody) i auf-schrei-ben (bezokolicznik na końcu po *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Co znaczy wyrażenie „eine Entscheidung treffen”? Nigdy go nie słyszałem.","why":"Aus-druck: *der Ausdruck* = wyrażenie; *der* i *Den* pokazują, że to rodzaj męski. (*eine Entscheidung treffen* = podjąć decyzję.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Niestety często zapominam ważne niemieckie słowa. Potrzebuję więcej czasu na powtórki.","why":"Wie-der-ho-lung: *zur* = *zu der*, więc dalej stoi rzeczownik rodzaju żeńskiego: *die Wiederholung* (powtórka, powtarzanie).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Nauka języków obcych – ale jak?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Nauka języków obcych – ale jak?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Kto co mówi? Przeczytaj trzy teksty i po każdym zdaniu napisz literę tekstu (A, B lub C).","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"Często słucham innych ludzi. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"W drodze do szkoły uczę się słówek. → A (Mila)","why":"Mila wyjmuje fiszki podczas godzinnej jazdy pociągiem do szkoły.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Po szkole chciałbym pracować w Anglii. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Oglądam dużo niemieckojęzycznej telewizji. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"Piszę fiszki ze słówkami. → A (Mila)","why":"Mila pisze obce słowo po jednej stronie kartki, a tłumaczenie po drugiej.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Napisz drugie zdanie: zacznij od podanego słowa (Deshalb, Darum …) i użyj słów w nawiasach. Czasownik stoi zaraz po słowie na początku.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"Dlatego powtarza nowe słówka za pomocą fiszek.","why":"*Darum* zajmuje pierwsze miejsce, więc zaraz po nim stoi odmieniony czasownik *wiederholt*, a potem podmiot *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Z tego powodu ma w smartfonie dużo podcastów.","why":"*Aus diesem Grund* zajmuje pierwsze miejsce tak jak *deshalb*: zaraz potem czasownik *hat*, potem *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"Dlatego chce dobrze mówić po angielsku.","why":"*Deswegen* + czasownik modalny *will* na drugim miejscu, bezokolicznik *sprechen* na końcu.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Dlatego ogląda dużo niemieckojęzycznej telewizji.","why":"*Daher* znaczy to samo co *deshalb*; czasownik *schaut* stoi zaraz po nim.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Z tego powodu po prostu zawsze i wszędzie słucha Szwajcarów.","why":"*zuhören* jest czasownikiem rozdzielnie złożonym: *hört … zu*. Polecenie podaje *zugehört*, więc Perfekt *hat … zugehört* (jak w tekście Danili) też jest poprawny.","source":"hueber","check":"Oficjalny klucz podaje czas teraźniejszy (*hört … zu*), chociaż polecenie podaje imiesłów *zugehört*. Oba zdania są poprawne po niemiecku; zapytaj nauczyciela, którą wersję chce książka."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test z lekcji 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij tekst Arifa. Książka podaje pierwszą literę i kilka liter w środku każdego słowa; wpisz całe słowo.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… a naszym językiem ojczystym jest arabski.","why":"*die Muttersprache* = pierwszy język, z którym się dorasta."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"Dlatego chciałbym poprawić swój niemiecki.","why":"Układ liter (D, e, e) pasuje do *Deswegen*; podaje skutek, a czasownik *möchte* stoi zaraz po nim.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Oczywiście nie będę wtedy jeszcze mówić płynnie po niemiecku.","why":"*fliessend* = płynny, płynnie. Pisownia szwajcarska z *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Szczególnie trudne wydają mi się pismo i wymowa …","why":"*die Aussprache* = wymowa (*aussprechen* = wymawiać)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… i też jeszcze nie rozumiem wszystkich wyrażeń.","why":"*der Ausdruck, die Ausdrücke* = wyrażenie, wyrażenia; *alle* wymaga liczby mnogiej."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Napisz nierzeczywiste zdania warunkowe z *wenn* i trybem przypuszczającym Konjunktiv II (*wäre, hätte, könnte, müsste* lub *würde* + bezokolicznik).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Gdyby mój angielski był lepszy, mógłbym ci pomóc w zadaniu domowym.","why":"*sein* → **wäre** na końcu zdania z *wenn*; *können* → **könnte**, potem zdanie główne zaczyna się od czasownika.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Lepiej bym was rozumiał, gdybyście nie mówili wszyscy naraz.","why":"Najpierw zdanie główne; *würde* + bezokolicznik w obu częściach. W zdaniu z *wenn* forma *würdet* idzie na koniec.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"Miałbym więcej czasu wolnego, gdybym nie musiał tyle pracować.","why":"*haben* → **hätte**, *müssen* → **müsste** (na końcu zdania z *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij słowem z ramki. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie (odpowiedź do a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Dlaczego Costa chce zostać mechatronikiem? – Bo interesuje się samochodami.","why":"Potrzebny jest zaimek pytający; **Weshalb** = *warum* (dlaczego). Wydrukowana odpowiedź zaczyna się od *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Dzięki dobrej znajomości niemieckiego szybko znalazł miejsce nauki zawodu.","why":"Dalej stoi grupa rzeczownikowa (*seiner guten Deutschkenntnisse*, dopełniacz liczby mnogiej) → przyimek **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Ma dopiero 17 lat. Dlatego wciąż mieszka u rodziców.","why":"Skutek, a czasownik stoi zaraz po luce (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Teraz oszczędza pieniądze, bo po nauce zawodu chciałby mieć własne mieszkanie.","why":"Przyczyna, a czasownik zostaje na drugim miejscu (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"Jak inaczej można to powiedzieć? Uzupełnij drugi zwrot. Książka podaje kilka liter; wpisz całe słowa.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"Mam pytanie. – Czy mogę Pana o coś zapytać?","why":"Grzeczny sposób, żeby zacząć pytanie: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Czy mógłby Pan to jeszcze raz powiedzieć? – Czy mógłby Pan to powtórzyć?","why":"*wiederholen* = powtórzyć = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Co ma Pan na myśli, mówiąc …? – Co znaczy …?","why":"*Was bedeutet …?* pyta o znaczenie, tak jak *Was meinen Sie mit …?*","check":"Litery w tej luce są na zdjęciu słabo czytelne; *Was bedeutet …?* do nich pasuje i jest zwrotem z ćwiczenia 13. Zapytaj nauczyciela, jeśli w twojej książce jest coś innego."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Przepraszam. – Przykro mi.","why":"*Tut mir leid* = przykro mi, inny sposób, żeby przeprosić."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Praca w centrum uwagi: szukanie pracy","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf szuka nowej pracy jako fryzjer. Czyta broszurę ze wskazówkami, jak szukać pracy. Przeczytaj wskazówki i po każdym akapicie napisz literę pasującego nagłówka (A–E).","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Akapit 1 (lista osób, które znasz) → C, Twoja osobista sieć kontaktów","why":"Przyjaciele, koledzy z pracy i byli pracodawcy to twoja osobista sieć kontaktów.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Akapit 2 (twoje własne ogłoszenie w internecie) → A, Ogłoszenie o szukaniu pracy w internecie","why":"*das Stellengesuch* = ogłoszenie, w którym szukasz pracy; tutaj na portalu internetowym.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Akapit 3 (krótkie podanie o pracę do wymarzonej firmy) → E, Aplikacja z własnej inicjatywy","why":"Zgłaszasz się do firmy, która nie ogłosiła oferty pracy: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Akapit 4 (ubieganie się o pracę przez telefon) → D, Ubieganie się o pracę przez telefon","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Akapit 5 (analiza ogłoszeń o pracę w internecie) → B, Ogłoszenia o pracę","why":"*das Stelleninserat* (szwajcarskie słowo) = ogłoszenie o pracę zamieszczone przez firmę.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf postanowił wziąć sprawy w swoje ręce i napisał ogłoszenie, że szuka pracy. Przeczytaj jego tekst i znajdź: kim jest Yusuf i jaki jest, co potrafi i czego szuka. Przy każdym pytaniu wypisz pasujące słowa.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"zaangażowany fryzjer, kreatywny i elastyczny, 24 lata","why":"Kim jest (zawód, wiek) i jaki jest (przymiotniki).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"sześć lat doświadczenia zawodowego, różne szkolenia z doradztwa w zakresie stylu","why":"Co oferuje: doświadczenie i szkolenia.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"wyzwanie, przy którym może nauczyć się nowych rzeczy i dalej się specjalizować","why":"Ostatnie zdanie: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Zamieść w internecie ogłoszenie o poszukiwaniu pracy. Szukasz nowej pracy. Zrób tabelę z trzema kolumnami (Kim jestem i jaki/jaka jestem? Co potrafię? Czego szukam?), potem napisz tekst profilu taki jak tekst Yusufa w 2. Przykładowa odpowiedź to jedna z możliwości.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Kim jestem i jaka jestem? elastyczna, umiejąca pracować w zespole, solidna, towarzyska | Co potrafię? dobrze obsługiwać klientów, dobra znajomość komputera, płynny niemiecki i angielski | Czego szukam? pracy na część etatu od przyszłego miesiąca, międzynarodowego zespołu","why":"Wystarczy kilka słów kluczowych w każdej kolumnie; użyj zwrotów z ramki.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Szukają Państwo solidnej sprzedawczyni, która umie pracować w zespole i jest towarzyska? Potrafię dobrze obsługiwać klientów, dobrze znam się na komputerach i mówię płynnie po niemiecku i angielsku. Od przyszłego miesiąca szukam pracy na część etatu w międzynarodowym zespole.","why":"Te same trzy kroki co u Yusufa: kim jesteś, co potrafisz, czego szukasz. *die* w zdaniu względnym odnosi się do *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Gramatyka","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Życzenie i rzeczywistość?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina musi zrobić jedno, ale wolałaby zrobić coś innego. Napisz, co wolałaby robić, używając *würde* + słów w nawiasach (z *lieber*, a w punkcie 5 z *gern*).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Ale wolałaby słuchać muzyki.","why":"*würde* na drugim miejscu, *lieber* = raczej, bezokolicznik *hören* na końcu.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Ale wolałaby porozmawiać przez telefon z przyjaciółką.","why":"*würde* + *lieber* + bezokolicznik na końcu.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Ale wolałaby grać w gry komputerowe.","why":"*würde* + *lieber* + bezokolicznik na końcu.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Ale chętnie czytałaby do późnej nocy.","why":"Książka podaje *gern*: *würde* + *gern* + bezokolicznik (życzenie), z *aber* po czasowniku.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Ale wolałaby pójść potańczyć.","why":"*würde* + *lieber*; oba bezokoliczniki *tanzen gehen* na końcu.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Przepisz zdania z a jako nierzeczywiste zdania warunkowe: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Gdyby Nina nie musiała uczyć się do egzaminu językowego, słuchałaby muzyki.","why":"*muss* → **müsste** na końcu zdania z *wenn*; zdanie główne zaczyna się od *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Gdyby Nina nie musiała sprzątać swoich ubrań, rozmawiałaby przez telefon z przyjaciółką.","why":"*müsste* + bezokolicznik *aufräumen*: w zdaniu z *wenn* *müsste* stoi na końcu.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Gdyby Nina nie pracowała przy komputerze, grałaby w gry komputerowe.","why":"Klucz akceptuje w zdaniu z *wenn* zarówno *arbeiten würde*, jak i *arbeiten müsste*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Gdyby Nina nie miała jutro bardzo wcześnie umówionego spotkania, czytałaby do późnej nocy.","why":"*hat* → **hätte**, na końcu zdania z *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Gdyby Nina nie spędzała wieczoru z rodzicami, poszłaby potańczyć.","why":"*würde* + bezokolicznik w obu częściach; *verbringen würde* na końcu zdania z *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Uzupełnij słowem *darum*, *weil* lub *wegen*. Każde słowo jest użyte dwa razy.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Wielu Niemców nie słyszy błędów gramatycznych Majida, bo ma on bardzo dobrą wymowę.","why":"Przyczyna, a czasownik *hat* stoi na końcu → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko nie zdał egzaminu, dlatego chce teraz zrobić kurs intensywny.","why":"Skutek, a czasownik *will* stoi zaraz po luce → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan chce pracować jako lekarz w niemieckim szpitalu, dlatego potrzebuje bardzo dobrej znajomości niemieckiego.","why":"Skutek + czasownik zaraz po luce (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla jest menedżerką i z powodu wielu konferencji nie może regularnie chodzić na kurs niemieckiego.","why":"Dalej stoi grupa rzeczownikowa (*ihrer vielen Konferenzen*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Borisa z powodu akcentu od razu rozpoznaje się jako Rosjanina.","why":"Grupa rzeczownikowa w dopełniaczu (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja chętnie nauczyłaby się arabskiego, bo pismo arabskie wydaje jej się takie piękne.","why":"Przyczyna z czasownikiem *findet* na końcu → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Słownictwo","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij tekst Ferdeza słowami z ramki. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie. Karta pracy używa pisowni z Niemiec z ostrym s; tutaj jest pisownia szwajcarska z *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"W macedońskim używa się cyrylicy. Dlatego na początku nie było mi łatwo pisać po niemiecku.","why":"*die kyrillische Schrift* = cyrylica."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Od ośmiu lat mieszkam w Bawarii. Teraz mówię już płynnie po niemiecku, tak uważam.","why":"*fliessend Deutsch sprechen* = mówić płynnie po niemiecku."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Ale moi koledzy z północnych Niemiec mówią, że mam bawarski akcent!","why":"*einen … Akzent haben* = mieć akcent; *einen bayerischen* → rzeczownik rodzaju męskiego."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Kiedy klnę po bawarsku, moi koledzy pękają ze śmiechu.","why":"*schimpfen* = narzekać, kląć; *ich schimpfe* na końcu zdania z *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Kiedy porównuję ze sobą niemiecki, macedoński i albański, zauważam, …","why":"*miteinander vergleichen* = porównywać ze sobą; *ich vergleiche* na końcu zdania z *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… że nie wszystkie słowa da się naprawdę dobrze przetłumaczyć na drugi język. Dziś czuję się jak w domu i w Macedonii, i w Niemczech.","why":"*in eine Sprache übersetzen* = tłumaczyć na jakiś język; bezokolicznik przed *kann* na końcu zdania z *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Co znaczy przysłowie „Lügen haben kurze Beine“ (kłamstwa mają krótkie nogi)? Wpisz A lub B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: Prawda zawsze szybko wychodzi na jaw. Dlatego nie należy kłamać.","why":"Kłamstwo nie zajdzie daleko, jak ktoś na krótkich nogach: szybko wychodzi na jaw. B to żart z dosłownego znaczenia słów."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Które słowo z ramki mogłoby zastąpić podkreślone słowo? Napisz je. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie. Podkreślone słowa są tu pogrubione.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Ja sam urodziłem się jednak w Moguncji.","why":"*allerdings* = *aber*: ogranicza to, co powiedziano wcześniej."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"Rodzice zawsze mówili do mnie po niemiecku, dlatego niestety nie znam farsi.","why":"*deswegen* = *deshalb* (skutek, czasownik stoi zaraz potem).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Teraz chodzę na kurs językowy. Uważam, że farsi jest tak samo trudny jak niemiecki.","why":"*ebenso … wie* = *genauso … wie* = tak samo … jak."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Zwłaszcza pismo! Jestem kimś, kto musi zapisywać wszystkie nowe słowa.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = zapisać coś sobie."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"To trudne, kiedy musisz to robić w piśmie, którego dopiero stopniowo się uczysz.","why":"*allmählich* = powoli, krok po kroku, stopniowo."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"Wymowa też nie jest łatwa. Jest taki dźwięk „gh”, którego nie umiem poprawnie wymówić.","why":"*korrekt* = *richtig* = poprawnie."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Kiedyś się uda – przynajmniej mam taką nadzieję!","why":"*irgendwann* = kiedyś, pewnego dnia = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Czytanie","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Przeczytaj odpowiedzi na ankietę „Czy nauka niemieckiego jest ważna?” i wybierz właściwe zakończenie każdego zdania. Wpisz zakończenie (albo tylko jego pierwsze słowa).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Kto dobrze zna angielski, i tak musi się dobrze nauczyć niemieckiego.","why":"Bradowi, dla którego angielski jest językiem ojczystym, w kółko powtarzano: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Niemcy najwyraźniej uważają, że bez perfekcyjnego niemieckiego nie ma się kwalifikacji zawodowych.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena ma nadzieję, że z certyfikatem z niemieckiego (Zertifikat Deutsch) znajdzie pracę w Austrii.","why":"Alena liczy na dobre szanse *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"Jako Polka Ewa chce znać niemiecki, bo Niemcy i Polska mają wspólną historię.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa żałuje, że niewielu Niemców interesuje się językiem polskim.","why":"Ewa chciałaby, żeby więcej Niemców interesowało się polskim."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha nauczyła się niemieckiego od męża.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Ma problemy, bo nie rozumie wystarczająco dobrze nauczycieli.","why":"Z wychowawcą klasy i na zebraniach z rodzicami ma *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Do pozwolenia na pracę wymagana jest dobra znajomość niemieckiego.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah chce dobrze znać niemiecki, bo mieszka w Niemczech.","why":"Chce znać język *des Landes …, in dem ich lebe*; jego niemiecki już wystarcza do rozmów z pacjentami."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha uczy się niemieckiego ze względu na dzieci.","why":"Jej dzieci narzekały, że jej niemiecki jest taki słaby, a teraz pomagają jej się uczyć."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Mówienie","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Która odpowiedź pasuje najlepiej? Po każdym zdaniu wpisz numer odpowiedzi (1–6). (Ćwiczenie 6 na tej stronie to zadanie ze słuchania i zostało pominięte.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Nazywam się Kranitzky-Krampe. → 5 Przepraszam, jak brzmi Pana nazwisko?","why":"Długie, nietypowe nazwisko: dopytujesz."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Na ubrania można też powiedzieć „Klamotten”. → 4 Nigdy nie słyszałem tego słowa.","why":"Nowe (potoczne) słowo: *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Co znaczy to słowo? → 1 Niestety też nie wiem.","why":"Odpowiedź na pytanie, na które nie znasz odpowiedzi."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"Naprawdę miałem wtedy szczęście. → 6 Czy dobrze zrozumiałem: miał Pan szczęście?","why":"*Schwein haben* (potocznie) = mieć szczęście; sprawdzasz, czy dobrze zrozumiałeś."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Czy mógłby Pan mówić trochę wolniej? → 3 Dobrze, postaram się.","why":"Odpowiedź na prośbę."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Napisz pytania zależne ze słowami w nawiasach. W pytaniu zależnym czasownik idzie na koniec.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Czy może mi Pan powiedzieć, dokąd mam zanieść śmieci?","why":"*wohin* zaczyna pytanie zależne; odmieniony czasownik *muss* idzie na koniec."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Czy może mi Pani powiedzieć, gdzie Panią boli?","why":"Pyta lekarz: *wo* + podmiot + czasownik na końcu (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Czy wie Pan może, czy ten pociąg jedzie do Berlina?","why":"Pytanie typu tak/nie staje się zależne z *ob*; czasownik *fährt* idzie na koniec."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Pisanie","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Wybierz język, którego chcesz się nauczyć, i napisz wiadomość do szkoły językowej: jaki język, kiedy i ile razy w tygodniu masz czas, w jakich terminach i godzinach są kursy, ile kosztuje kurs i jak długo trwa; poproś o odpowiedź i użyj odpowiedniego powitania i zakończenia. Przykładowa odpowiedź jest zgodna z oficjalnym kluczem.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Szanowni Państwo, chciałbym nauczyć się nowogreckiego. Mam czas od poniedziałku do czwartku wieczorami i mógłbym przychodzić dwa razy w tygodniu. Proszę o informację, w jakich godzinach oferują Państwo kurs języka nowogreckiego. Musiałbym też wiedzieć, ile kosztuje kurs i jak długo trwa. Proszę o krótką odpowiedź. Z poważaniem …","why":"List formalny: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Pytania są zależne (*zu welchen Zeiten …, wie viel …, wie lange …*): czasownik na końcu."}]}]}]}];
